@@ -0,0 +1,42 @@
+export async function callAssessmentApi(payload: unknown) {
+  const res = await fetch('https://api.assessor.example/v1/score', {
+    method: 'POST',
+    headers: { 'Authorization': 'Bearer ' + ENV.ASSESSOR_KEY },
+    body: JSON.stringify(payload),
+  });
+
+  if (!res.ok) {
+    throw new Error('Assessment API failed: ' + res.status);
+  }
+
+  return res.json();
+}
